extends CharacterBody3D
class_name PedestrianAgent

@export var walk_speed := 2.2
@export var wander_radius := 14.0
@export var pause_min := 0.8
@export var pause_max := 2.8
@export var signal_stop_distance := 4.5

var origin := Vector3.ZERO
var target := Vector3.ZERO
var pause_left := 0.0
var rng := RandomNumberGenerator.new()
var route_points: Array[Vector3] = []
var route_index := 0
var traffic_coordinator = null

func _ready() -> void:
    origin = global_position
    rng.randomize()
    _pick_target()

func _physics_process(delta: float) -> void:
    if pause_left > 0.0:
        pause_left -= delta
        velocity = Vector3.ZERO
        move_and_slide()
        return
    if not route_points.is_empty():
        target = route_points[route_index]

    var flat := target - global_position
    flat.y = 0.0
    if flat.length() < 0.8:
        pause_left = rng.randf_range(pause_min, pause_max)
        if not route_points.is_empty():
            route_index = (route_index + 1) % route_points.size()
            target = route_points[route_index]
        else:
            _pick_target()
        return
    var dir := flat.normalized()
    if _must_wait_for_crossing_signal(dir, flat.length()):
        velocity = Vector3.ZERO
        move_and_slide()
        return
    velocity.x = dir.x * walk_speed
    velocity.z = dir.z * walk_speed
    if not is_on_floor():
        velocity.y -= 16.0 * delta
    else:
        velocity.y = -0.1
    rotation.y = lerp_angle(rotation.y, atan2(dir.x, dir.z), 7.0 * delta)
    move_and_slide()

func _pick_target() -> void:
    var a := rng.randf_range(0.0, TAU)
    var r := rng.randf_range(4.0, wander_radius)
    target = origin + Vector3(cos(a) * r, 0.0, sin(a) * r)


func set_route(points: Array[Vector3]) -> void:
    route_points = points
    route_index = 0
    if not route_points.is_empty():
        target = route_points[0]

func configure_traffic_coordinator(value) -> void:
    traffic_coordinator = value

func _must_wait_for_crossing_signal(direction: Vector3, distance_to_target: float) -> bool:
    if traffic_coordinator == null:
        return false
    if not traffic_coordinator.has_method("nearest_intersection_index"):
        return false
    if not traffic_coordinator.has_method("pedestrian_allows_crossing"):
        return false
    var intersection_idx: int = int(traffic_coordinator.nearest_intersection_index(target))
    if intersection_idx < 0:
        return false
    if distance_to_target > signal_stop_distance:
        return false
    return not bool(traffic_coordinator.pedestrian_allows_crossing(intersection_idx, direction))

